<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, ref, watch } from 'vue';
import { Copy, Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, Box, Check, ChevronDown, ChevronRight, CircleHelp, ClipboardList, Clock3, Database, Download, FileJson, FileSpreadsheet, FolderOpen, HardDrive, History, Layers3, LayoutDashboard, LayoutGrid, ListFilter, LoaderCircle, MapPin, Maximize2, Minus, Monitor, MoreHorizontal, Network, Plus, RefreshCw, Search, Server, Settings2, ShieldCheck, Snowflake, Upload, X, Zap } from 'lucide-vue-next';
import {parseNavigation,navigationHash} from './navigationState';
import SpaceDeleteDialog from './SpaceDeleteDialog.vue';
import DiagramExport from './DiagramExport.vue';
import ViewControls from './ViewControls.vue';
import {displayPreferences as display,displayClasses} from './displayPreferences';
import ActionMenu from './ActionMenu.vue';
import {systemInfo} from './systemInfo';
import InitializationWizard from './InitializationWizard.vue';import TemplateLibrary from './TemplateLibrary.vue';import TemplateEditor from './TemplateEditor.vue';import {captureModulePlan} from './templatePlan';import ProjectOverview from './ProjectOverview.vue';import EditorPage from './EditorPage.vue';import {useDeviceDrag} from './useDeviceDrag';import TopologyView from './TopologyView.vue';import RoomOverview from './RoomOverview.vue';import LayoutEditor from './LayoutEditor.vue';import FloorPlan from './FloorPlan.vue';import RackElevation from './RackElevation.vue';import Modal from './Modal.vue';
import { blankDevice, blankModel, download, request, roleColors, roleNames, sampleCSV, statuses, moduleProducts } from './model';
import type { Audit, Device, Model, Preview, State, Infra, ModuleTemplate } from './model';
const state=ref<State|null>(null), loading=ref(true), loadError=ref(''), busy=ref(false), toast=ref(''), formError=ref('');
const navs=[{id:'overview',name:'空间总览',icon:LayoutDashboard},{id:'topology',name:'网络拓扑',icon:Network},{id:'assets',name:'设备台账',icon:ClipboardList},{id:'models',name:'型号库',icon:Layers3},{id:'templates',name:'布局模板',icon:Copy},{id:'audit',name:'变更审计',icon:History}];
const view=ref(parseNavigation(location.hash).view);
let restoring=false,routeTimer:ReturnType<typeof setTimeout>|undefined;
const topologyNetworkID=ref(''),topologyReturn=ref(false);
const topology=ref<{navigate:(id:string,root?:boolean)=>void;dropNetwork:(event:DragEvent,parentId:string)=>void}>();
const topologyNavigation=ref<{path:{id:string;name:string}[];busy:boolean}>({path:[],busy:false});
const navigationBusy=computed(()=>busy.value||topologyNavigation.value.busy);
const spaceDelete=ref<{kind:'module'|'rack';id:string}|null>(null);
function openSpaceDelete(kind:'module'|'rack',id:string){if(!navigationBusy.value)spaceDelete.value={kind,id}}
function spaceDeleted(next:State){busy.value=false;state.value=next;spaceDelete.value=null;if(!next.racks.some(r=>r.id===rackID.value))rackID.value='';if(!next.modules.some(m=>m.id===moduleID.value)){modal.value='';moduleID.value=modules.value[0]?.id||'';view.value='room'}notify('删除完成，变更已记录审计')}
const floorPlan=ref<{fit:()=>void}>();
const templateForm=ref<ModuleTemplate>();const templateSelection=ref('');
const topologyEditTitle=ref('');
const projectID=ref('');const layoutModuleID=ref(''),layoutInitial=ref<Infra>();const renameName=ref('');const renameProject=ref('');
const siteID=ref(''),moduleID=ref(''),rackID=ref(''),deviceID=ref(''),query=ref(''),statusFilter=ref(''),zoom=ref(100),assetPage=ref(1);
const selectedInfraID=ref('');const elevationScale=ref(90),rackRow=ref('all'),compareMode=ref(false),compareRackID=ref('');
const modal=ref(''),deviceForm=ref(blankDevice()),modelForm=ref(blankModel()),autoPlace=ref(true),audits=ref<Audit[]>([]),deleteTarget=ref<{kind:'devices'|'models';id:string;name:string}|null>(null);
type WizardModule = { rack_names?:Record<string,string[]>; product_model?:string;point?:string;layout?:unknown[]; name: string; type: string; rack_count: number; rack_left: number; rack_right: number; u_height: number; infra?: {power:number;ac:number;env:number} };
const wizard=ref<{project_id:string;project_name:string;site_name:string;site_id:string;modules:WizardModule[];infra:{power:number;ac:number;env:number}}>({project_id:'',project_name:'',site_name:'',site_id:'',modules:[{name:'单排微模块',point:'',product_model:moduleProducts[0],type:'single',rack_count:4,rack_left:4,rack_right:4,u_height:42}],infra:{power:1,ac:1,env:1}});
const previewSource=ref<{content:string;moduleId:string}|null>(null);
const csvContent=ref(''),csvName=ref(''),importModule=ref(''),preview=ref<Preview|null>(null);
const projects=computed(()=>state.value?.projects||[]);
const sites=computed(()=>state.value?.sites.filter(s=>s.projectId===projectID.value)||[]),modules=computed(()=>state.value?.modules.filter(m=>m.siteId===siteID.value)||[]);
const currentProject=computed(()=>projects.value.find(p=>p.id===projectID.value));
const layoutModule=computed(()=>state.value?.modules.find(m=>m.id===layoutModuleID.value));
const currentSite=computed(()=>sites.value.find(s=>s.id===siteID.value)),currentModule=computed(()=>modules.value.find(m=>m.id===moduleID.value));
const racks=computed(()=>(state.value?.racks.filter(r=>r.moduleId===moduleID.value)||[]).sort((a,b)=>a.side.localeCompare(b.side)||a.index-b.index)),currentRack=computed(()=>racks.value.find(r=>r.id===rackID.value));
const siteModuleIDs=computed(()=>new Set(modules.value.map(m=>m.id))),siteRacks=computed(()=>state.value?.racks.filter(r=>siteModuleIDs.value.has(r.moduleId))||[]),siteDevices=computed(()=>state.value?.devices.filter(d=>siteModuleIDs.value.has(d.moduleId))||[]);
const moduleDevices=computed(()=>siteDevices.value.filter(d=>d.moduleId===moduleID.value)),rackDevices=computed(()=>moduleDevices.value.filter(d=>d.rackId===rackID.value));
const pending=computed(()=>moduleDevices.value.filter(d=>!d.rackId));
const selectedDevice=computed(()=>state.value?.devices.find(d=>d.id===deviceID.value));
const modelOf=(id:string)=>state.value?.models.find(m=>m.id===id);
const rackName=(id:string)=>state.value?.racks.find(r=>r.id===id)?.name||'待上架';
const moduleName=(id:string)=>state.value?.modules.find(m=>m.id===id)?.name||'—';
const usedU=(id:string)=>state.value?.devices.filter(d=>d.rackId===id).reduce((sum,d)=>sum+(modelOf(d.modelId)?.uHeight||0),0)||0;
const totalUsed=computed(()=>siteRacks.value.reduce((n,r)=>n+usedU(r.id),0));
const usage=computed(()=>siteRacks.value.length?Math.round(totalUsed.value/(siteRacks.value.length*42)*100):0);
const filteredDevices=computed(()=>siteDevices.value.filter(d=>(!statusFilter.value||d.status===statusFilter.value)&&(!query.value||[d.name,d.assetTag,d.ip,d.sn,modelOf(d.modelId)?.name].join(' ').toLowerCase().includes(query.value.toLowerCase()))));
const pageDevices=computed(()=>filteredDevices.value.slice((assetPage.value-1)*20,assetPage.value*20));
const filteredModels=computed(()=>state.value?.models.filter(m=>[m.name,m.vendor,roleNames[m.role]].join(' ').toLowerCase().includes(query.value.toLowerCase()))||[]);
const deviceRacks=computed(()=>state.value?.racks.filter(r=>r.moduleId===deviceForm.value.moduleId)||[]);
const editingPage=computed(()=>['layout','device','rack','model','renameProject','renameRoom','wizard','import','template','initialize'].includes(modal.value));
const rackEditName=ref('');
const selectedInfra=computed(()=>state.value?.infra.find(i=>i.id===selectedInfraID.value));
const shownRacks=computed(()=>compareMode.value?racks.value.filter(r=>r.id===rackID.value||r.id===compareRackID.value):racks.value.filter(r=>rackRow.value==='all'||r.side===rackRow.value));
const dragDevices=useDeviceDrag(()=>state.value?.devices||[],()=>state.value?.models||[],moveDevice,id=>{deviceID.value=id;const d=state.value?.devices.find(d=>d.id===id);if(d?.rackId)rackID.value=d.rackId},()=>!busy.value);
const breadcrumbDevice=computed(()=>modal.value==='device'?state.value?.devices.find(d=>d.id===deviceForm.value.id):undefined);
const breadcrumbModule=computed(()=>breadcrumbDevice.value?state.value?.modules.find(m=>m.id===breadcrumbDevice.value!.moduleId):currentModule.value);
const breadcrumbRack=computed(()=>breadcrumbDevice.value?state.value?.racks.find(r=>r.id===breadcrumbDevice.value!.rackId):currentRack.value);
const breadcrumbRoom=computed(()=>editingPage.value&&breadcrumbModule.value?state.value?.sites.find(r=>r.id===breadcrumbModule.value!.siteId):currentSite.value);
const spatialView=computed(()=>['overview','room','module','elevation'].includes(view.value));
const activeNav=computed(()=>spatialView.value?'overview':view.value);
const title=computed(()=>view.value==='room'?(currentSite.value?.name||'机房总览'):view.value==='module'?(currentModule.value?.name||'微模块'):view.value==='elevation'?'机柜立面':navs.find(n=>n.id===view.value)?.name||'空间总览');
let toastTimer:ReturnType<typeof setTimeout>;
function notify(message:string){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',5000)}
async function load(){const initial=!state.value;loading.value=true;loadError.value='';try{state.value=await request<State>('/state');if(!projectID.value)projectID.value=state.value.projects[0]?.id||'';if(!siteID.value)siteID.value=sites.value[0]?.id||'';if(initial)await restoreNavigation();if(view.value==='audit')await loadAudits()}catch(e){loadError.value=(e as Error).message||'无法连接后台'}finally{loading.value=false}}
async function loadAudits(){try{audits.value=await request<Audit[]>('/audits')}catch(e){notify((e as Error).message)}}
async function compactAudits(){
 if(busy.value)return;busy.value=true;
 try{const result=await request<{removed:number;compacted:number;bytesBefore:number;bytesAfter:number;warning?:string}>('/audits/compact','POST',{revision:state.value!.revision});await loadAudits();notify(result.warning||`已移除 ${result.removed} 条非业务记录，精简 ${result.compacted} 条记录；审计正文减少 ${Math.max(0,(result.bytesBefore-result.bytesAfter)/1024).toFixed(1)} KB`)}catch(e){notify((e as Error).message);if((e as {status?:number}).status===409)await load()}finally{busy.value=false}
}
watch(projectID,()=>{topologyReturn.value=false;if(!restoring)topologyNetworkID.value='';if(!sites.value.some(s=>s.id===siteID.value))siteID.value=sites.value[0]?.id||'';if(!restoring&&['room','module','elevation'].includes(view.value))view.value='overview'});
watch(siteID,()=>{moduleID.value=modules.value[0]?.id||'';query.value='';assetPage.value=1});watch(moduleID,()=>{rackID.value=view.value==='elevation'?racks.value[0]?.id||'':'';zoom.value=100;deviceID.value='';selectedInfraID.value='';compareMode.value=false;rackRow.value='all';dragDevices.cancel()});
watch(view,()=>{if(view.value==='elevation')selectedInfraID.value='';if(view.value==='module')deviceID.value='';if(view.value==='elevation'&&!rackID.value)rackID.value=racks.value[0]?.id||'';if(!['module','elevation'].includes(view.value))clearSelection();query.value='';assetPage.value=1;if(view.value==='audit')loadAudits();if(view.value!=='topology')topologyEditTitle.value=''});watch([query,statusFilter],()=>assetPage.value=1);
watch([csvContent,importModule],()=>preview.value=null);
watch(modal,()=>{formError.value='';if(editingPage.value)window.scrollTo({top:0,behavior:'instant'})});
async function mutate(path:string,method:string,payload:object,message:string,close=true){
 if(busy.value)return;busy.value=true;formError.value='';try{state.value=await request<State>(path,method,{revision:state.value!.revision,...payload});if(close)modal.value='';notify(message);if(view.value==='audit')await loadAudits()}catch(e){formError.value=(e as Error).message;notify((e as Error).message);if((e as {status?:number}).status===409)await load()}finally{busy.value=false}
}
function openInitialize(){modal.value='initialize'}
async function initialized(target:'room'|'topology',project:string,site:string){modal.value='';projectID.value=project;await nextTick();siteID.value=site;await nextTick();view.value=target;notify('初始化已完成')}
function newPlan(){templateSelection.value='';wizard.value={project_id:projectID.value,project_name:'',site_name:'',site_id:'',modules:[{name:'单排微模块',point:'',product_model:moduleProducts[0],type:'single',rack_count:4,rack_left:4,rack_right:4,u_height:42}],infra:{power:1,ac:1,env:1}};modal.value='wizard'}
function editTemplate(t:ModuleTemplate){templateForm.value=JSON.parse(JSON.stringify(t));modal.value='template'}
function saveModuleTemplate(){if(!state.value||!moduleID.value)return;const plan=captureModulePlan(state.value,moduleID.value);editTemplate({id:'',name:plan.name+' 布局模板',description:'',plan,updatedAt:''})}
function applyTemplate(id:string,index=0){const t=state.value?.templates.find(t=>t.id===id);if(!t)return;const plan=JSON.parse(JSON.stringify(t.plan));wizard.value.modules[index]={rack_count:4,rack_left:4,rack_right:4,...plan};templateSelection.value=id}
function useTemplate(t:ModuleTemplate){const target=view.value==='room'||view.value==='module'||view.value==='elevation'?siteID.value:'';newPlan();wizard.value.site_id=target;applyTemplate(t.id)}
function templateSaved(next:State){state.value=next;modal.value='';notify('布局模板已保存');view.value='templates'}
async function submitPlan(){const previous=new Set(state.value!.modules.map(m=>m.id));await mutate('/plans','POST',{plan:wizard.value},'机房规划已创建，基座与基础设施槽位已生成');if(!formError.value){const created=state.value?.modules.find(m=>!previous.has(m.id));if(created){projectID.value=state.value!.sites.find(s=>s.id===created.siteId)!.projectId;await nextTick();siteID.value=created.siteId;await nextTick();moduleID.value=created.id;view.value='room'}}}
async function readPlan(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;try{if(file.size>100000)throw new Error('规划文件过大');const p=JSON.parse(await file.text());if(!p.site_name||!Array.isArray(p.modules)||!p.infra)throw new Error('需要包含site_name、modules和infra的规划JSON');wizard.value={...p,project_id:projectID.value,project_name:'',site_id:'',modules:p.modules.map((m:any)=>({rack_count:4,rack_left:4,rack_right:4,...m}))};notify('已载入规划，请检查参数后创建')}catch(e){formError.value=(e as Error).message}(event.target as HTMLInputElement).value=''}
function openImport(){csvContent.value='';csvName.value='';preview.value=null;importModule.value=moduleID.value;modal.value='import'}
async function readCSV(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>2*1024*1024){formError.value='文件不能超过2MiB';return}try{const buffer=await file.arrayBuffer();csvContent.value=new TextDecoder('utf-8',{fatal:true}).decode(buffer);csvName.value=file.name;formError.value=''}catch{formError.value='请将CSV保存为UTF-8编码后再导入'}(event.target as HTMLInputElement).value=''}
async function previewCSV(){if(busy.value)return;busy.value=true;formError.value='';const source={content:csvContent.value,moduleId:importModule.value};try{const result=await request<Preview>('/import/preview','POST',{revision:state.value!.revision,...source});if(source.content===csvContent.value&&source.moduleId===importModule.value){preview.value=result;previewSource.value=source}else{formError.value='清单或目标模块已变化，请重新预览'}}catch(e){formError.value=(e as Error).message;if((e as {status?:number}).status===409)await load()}finally{busy.value=false}}
async function commitCSV(){if(!preview.value||preview.value.revision!==state.value!.revision||previewSource.value?.content!==csvContent.value||previewSource.value?.moduleId!==importModule.value){formError.value='数据已变化，请重新预览';preview.value=null;return}await mutate('/import/commit','POST',{moduleId:importModule.value,content:csvContent.value},'设备已导入，机位和变更记录已保存')}
function editDevice(d?:Device){if(d){const m=state.value?.modules.find(m=>m.id===d.moduleId);if(m&&m.id!==moduleID.value)moduleID.value=m.id;if(d.rackId)rackID.value=d.rackId}deviceForm.value=d?{...d}: {...blankDevice(),moduleId:moduleID.value,modelId:state.value?.models[0]?.id||'',assetTag:`AOM-${Date.now().toString().slice(-9)}`};autoPlace.value=!d;modal.value='device'}
function setDeviceRack(){if(deviceForm.value.rackId){deviceForm.value.startU=deviceForm.value.startU||1;deviceForm.value.status='installed'}else{deviceForm.value.startU=0;deviceForm.value.status='pending'}}
async function saveDevice(){const d={...deviceForm.value};if(!d.name)d.name=modelOf(d.modelId)?.name||'';await mutate('/devices'+(d.id?'/'+d.id:''),d.id?'PUT':'POST',{device:d,autoPlace:!d.id&&autoPlace.value},'设备台账已保存')}
function editModel(m?:Model){modelForm.value=m?{...m}:blankModel();modal.value='model'}
async function saveModel(){const m=modelForm.value;await mutate('/models'+(m.id?'/'+m.id:''),m.id?'PUT':'POST',{model:m},'型号已保存')}
function remove(kind:'devices'|'models',id:string,name:string){deleteTarget.value={kind,id,name};modal.value='delete'}
async function confirmDelete(){const d=deleteTarget.value!;await mutate('/'+d.kind+'/'+d.id,'DELETE',{},'记录已删除，审计快照已保留')}
async function moveDevice(id:string,rack:string,u:number){await mutate('/devices/'+id+'/placement','POST',{rackId:rack,startU:u},rack?'机位已更新':'设备已移至待上架区',false);if(!formError.value&&rack){const previous=rackID.value;rackID.value=rack;if(compareMode.value&&compareRackID.value===rack)compareRackID.value=previous;deviceID.value=id}}
async function openModule(id:string,rack?:string){if(navigationBusy.value)return;moduleID.value=id;await nextTick();if(rack){rackID.value=rack;view.value='elevation';await nextTick();document.querySelector(`[data-rack-id="${CSS.escape(rack)}"]`)?.scrollIntoView({behavior:'smooth',block:'start',inline:'center'})}else{clearSelection();view.value='module';await nextTick();document.getElementById('module-detail')?.scrollIntoView({behavior:'smooth',block:'start'})}}
function openLayout(item?:Infra){layoutModuleID.value=moduleID.value;layoutInitial.value=item;modal.value='layout'}
async function onLayoutSaved(next:State){state.value=next;if(!next.racks.some(r=>r.id===rackID.value))rackID.value='';const m=next.modules.find(m=>m.id===layoutModuleID.value);if(!m){modal.value='';moduleID.value=modules.value[0]?.id||'';view.value='room';busy.value=false;return}if(m){projectID.value=next.sites.find(s=>s.id===m.siteId)!.projectId;await nextTick();siteID.value=m.siteId;await nextTick();moduleID.value=m.id}}
function rename(kind:'project'|'room'){renameName.value=kind==='project'?currentProject.value?.name||'':currentSite.value?.name||'';renameProject.value=projectID.value;modal.value=kind==='project'?'renameProject':'renameRoom'}
async function saveName(){const room=modal.value==='renameRoom';await mutate(room?'/sites/'+siteID.value:'/projects/'+projectID.value,'PUT',{name:renameName.value,...(room?{projectId:renameProject.value}:{})},'名称与归属已保存');if(room&&!formError.value)projectID.value=renameProject.value}
async function locateTopologyDevice(d:Device){topologyReturn.value=true;const module=state.value!.modules.find(m=>m.id===d.moduleId)!;const room=state.value!.sites.find(s=>s.id===module.siteId)!;projectID.value=room.projectId;await nextTick();siteID.value=room.id;await nextTick();moduleID.value=module.id;await nextTick();deviceID.value=d.id;if(d.rackId){rackID.value=d.rackId;view.value='elevation';await nextTick();document.querySelector(`[data-rack-id="${CSS.escape(d.rackId)}"]`)?.scrollIntoView({behavior:'smooth',block:'start',inline:'center'})}else{view.value='assets';await nextTick();query.value=d.assetTag}}
async function enterRoom(id:string){if(navigationBusy.value)return;topologyReturn.value=false;siteID.value=id;view.value='room';await nextTick();window.scrollTo({top:0,behavior:'instant'})}
function selectRack(id:string,inspect=true){if(inspect)display.details=true;rackID.value=id;deviceID.value='';selectedInfraID.value=''}
function selectInfra(item:Infra,inspect=true){if(inspect)display.details=true;rackID.value='';selectedInfraID.value=item.id;deviceID.value=''}
function clearSelection(){rackID.value='';selectedInfraID.value='';deviceID.value=''}
async function moveModule(id:string,site:string){const module=state.value?.modules.find(m=>m.id===id);if(!module)return;await mutate('/modules/'+id,'PUT',{...module,siteId:site},'微模块已移入目标机房，柜内资产与网络连接保留',false)}
async function saveEntrance(entrance:import('./model').RoomEntrance|null){await mutate('/sites/'+siteID.value+'/entrance','PUT',{entrance},'机房入口已保存',false)}
async function positionModule(id:string,position:{x:number;y:number}|null,rotation?:number){await mutate('/modules/'+id+'/room-position','POST',{position,rotation},position?'模块位置已保存':'已恢复默认位置',false)}
async function moveInfrastructure(id:string,side:string,afterRack:number,beforeId:string){await mutate('/infrastructure/'+id+'/placement','POST',{side,afterRack,beforeId},'设施位置已保存',false);if(!formError.value){rackID.value='';selectedInfraID.value=id}}
async function insertCabinet(id:string,side:string,beforeId:string){await mutate('/modules/'+moduleID.value+'/rack-insert','POST',{rackId:id,side,beforeId},'机柜已插入指定位置',false)}
async function focusRack(id:string){rackID.value=id;deviceID.value='';if(compareMode.value&&compareRackID.value===id)compareRackID.value=racks.value.find(r=>r.id!==id)?.id||'';await nextTick();document.querySelector(`[data-rack-id="${CSS.escape(id)}"]`)?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})}
function toggleCompare(){compareMode.value=!compareMode.value;if(compareMode.value)compareRackID.value=racks.value.find(r=>r.id!==rackID.value)?.id||''}
function editRack(){rackEditName.value=currentRack.value?.name||'';modal.value='rack'}
async function saveRack(){await mutate('/racks/'+rackID.value,'PUT',{name:rackEditName.value},'机柜名称已保存')}
async function breadcrumb(level:string){if(navigationBusy.value)return;if(level==='project'&&view.value==='topology'){await navigateNetwork('',true);return;}if(level==='project'&&!spatialView.value){modal.value='';return;}const module=breadcrumbModule.value,room=breadcrumbRoom.value,rack=breadcrumbRack.value;modal.value='';selectedInfraID.value='';deviceID.value='';if(room&&level!=='project'){projectID.value=room.projectId;await nextTick();siteID.value=room.id;await nextTick()}if(module&&(level==='module'||level==='rack')){moduleID.value=module.id;await nextTick()}if(level==='project'||level==='room'){view.value=level==='project'?'overview':'room';await nextTick();document.querySelector('.room-overview')?.scrollIntoView({behavior:'smooth',block:'start'})}else if(level==='module'){view.value='module';await nextTick();document.getElementById('module-detail')?.scrollIntoView({behavior:'smooth',block:'start'})}else if(level==='rack'&&rack){view.value='elevation';await focusRack(rack.id)}}
function drag(event:DragEvent,id:string){event.dataTransfer!.setData('device',id);event.dataTransfer!.effectAllowed='move'}
const formatTime=(time:string)=>new Date(time).toLocaleString('zh-CN',{hour12:false});

async function navigateNetwork(id:string,root=false){if(navigationBusy.value)return;modal.value='';topologyReturn.value=false;view.value='topology';await nextTick();topology.value?.navigate(id,root);window.scrollTo({top:0,behavior:'instant'})}
async function navigateWorkspace(id:string){if(navigationBusy.value)return;modal.value='';topologyReturn.value=false;if(view.value==='topology'&&id!=='topology')topology.value?.navigate(topologyNetworkID.value);view.value=id;if(id==='topology'){await nextTick();topology.value?.navigate('',true)}window.scrollTo({top:0,behavior:'instant'})}
async function returnToTopology(){if(navigationBusy.value)return;modal.value='';view.value='topology';topologyReturn.value=false;await nextTick();window.scrollTo({top:0,behavior:'instant'})}
function currentRoute(){return {view:view.value,project:projectID.value,room:siteID.value,module:moduleID.value,rack:rackID.value,network:topologyNetworkID.value}}
function writeRoute(replace=false){if(!state.value||loading.value||restoring)return;const hash=navigationHash(currentRoute());if(location.hash!==hash)history[replace?'replaceState':'pushState'](null,'',hash)}
async function restoreNavigation(){
 if(!state.value||restoring)return;if(navigationBusy.value){history.pushState(null,'',navigationHash(currentRoute()));notify('正在保存，请完成后再切换页面');return}restoring=true;clearTimeout(routeTimer);
 try{
  const route=parseNavigation(location.hash);modal.value='';topologyReturn.value=false;
  projectID.value=projects.value.some(p=>p.id===route.project)?route.project:projects.value[0]?.id||'';await nextTick();
  siteID.value=sites.value.some(s=>s.id===route.room)?route.room:sites.value[0]?.id||'';await nextTick();
  moduleID.value=modules.value.some(m=>m.id===route.module)?route.module:modules.value[0]?.id||'';await nextTick();
  view.value=route.view;
  topologyNetworkID.value=state.value.networks.some(n=>n.id===route.network&&n.projectId===projectID.value)?route.network:'';
  await nextTick();if(route.view==='elevation')rackID.value=racks.value.some(r=>r.id===route.rack)?route.rack:racks.value[0]?.id||'';
  if(route.view==='topology'){await nextTick();topology.value?.navigate(topologyNetworkID.value,!topologyNetworkID.value)}
  if(['room','module','elevation'].includes(view.value)&&!currentSite.value)view.value='overview';
  else if(['module','elevation'].includes(view.value)&&!currentModule.value)view.value='room';
  await nextTick();history.replaceState(null,'',navigationHash(currentRoute()));
 }finally{restoring=false}
}
watch([view,projectID,siteID,moduleID,rackID,topologyNetworkID],()=>{if(restoring||loading.value)return;clearTimeout(routeTimer);routeTimer=setTimeout(()=>writeRoute(),0)},{flush:'post'});
onMounted(()=>window.addEventListener('popstate',restoreNavigation));
onBeforeUnmount(()=>{clearTimeout(routeTimer);window.removeEventListener('popstate',restoreNavigation)});
onMounted(load);
</script>

<template>
 <div v-if="!state" class="startup"><div class="brand-mark"><Layers3 :size="26"/></div><h1>AOM 机房数字孪生</h1><p v-if="loading">正在读取本地机房数据…</p><template v-else><p role="alert">{{loadError}}</p><button class="primary" @click="load">重新连接</button><small>请确认后台程序已启动。</small></template></div>
 <div v-else class="app-shell" :class="displayClasses">
  <aside class="sidebar">
   <a class="brand" href="#overview" @click.prevent="navigateWorkspace('overview')"><div class="brand-mark"><Layers3 :size="23"/></div><div><strong>AOM<span> /</span></strong><small>机房数字孪生</small></div></a>
   <div class="workspace-label"><span>工作空间</span></div>
   <nav aria-label="主导航"><button v-for="item in navs" :key="item.id" :aria-label="item.name" :title="item.name" :aria-current="activeNav===item.id?'page':undefined" :class="['nav-item',{active:activeNav===item.id}]" @click="navigateWorkspace(item.id)" :disabled="navigationBusy"><component :is="item.icon" :size="18"/><span>{{item.name}}</span><ChevronRight v-if="activeNav===item.id" class="nav-arrow" :size="14"/></button></nav>
   <div class="sidebar-separator"></div><div class="workspace-label"><span>{{currentProject?.name||'项目空间'}}</span><button class="side-icon" aria-label="编辑项目名称" @click="rename('project')"><Settings2 :size="13"/></button><button class="side-icon" aria-label="新建机房" @click="newPlan"><Plus :size="15"/></button></div>
   <button v-for="site in sites" :key="site.id" :class="['site-link',{selected:spatialView&&view!=='overview'&&siteID===site.id}]" @click="modal='';enterRoom(site.id)"><span class="site-dot"></span><span>{{site.name}}</span><span class="site-number">{{state.modules.filter(m=>m.siteId===site.id).length}}</span></button>
   <div class="sidebar-bottom"><div class="local-status"><span class="status-dot"></span><div><strong>本地工作空间</strong><small>已登录 · 数据加密保存</small></div><ShieldCheck :size="18"/></div><button class="help-button" @click="modal='help'"><CircleHelp :size="16"/><span>使用与部署说明</span><ArrowUpRight :size="14"/></button><p>AOM CONSOLE</p></div>
  </aside>
  <div class="app-main" :class="{'diagram-workspace':['room','module','elevation','topology'].includes(view),'topology-workspace-page':view==='topology'}">
   <header class="topbar"><nav class="breadcrumbs hierarchy-crumbs" aria-label="位置导航"><div class="project-picker"><FolderOpen :size="15"/><select v-model="projectID" aria-label="选择项目" :disabled="editingPage||!!topologyEditTitle||navigationBusy"><option v-for="project in projects" :key="project.id" :value="project.id">{{project.name}}</option></select></div><template v-if="view==='topology'"><nav class="topology-breadcrumb-trail" aria-label="网络层级"><ChevronRight :size="13"/><button class="crumb-home" :disabled="navigationBusy" :aria-label="`返回项目 ${currentProject?.name}`" :aria-current="!topologyNavigation.path.length&&!topologyEditTitle&&!editingPage?'page':undefined" @click="navigateNetwork('',true)" @dragover.prevent @drop="topology?.dropNetwork($event,'')">项目拓扑</button><template v-for="n in topologyNavigation.path" :key="n.id"><ChevronRight :size="13"/><button :disabled="navigationBusy" :aria-current="n.id===topologyNetworkID&&!topologyEditTitle&&!editingPage?'page':undefined" :data-network-drop="n.id" @click="navigateNetwork(n.id)" @dragover.prevent @drop="topology?.dropNetwork($event,n.id)">{{n.name}}</button></template><template v-if="topologyEditTitle&&!editingPage"><ChevronRight :size="13"/><strong aria-current="page">{{topologyEditTitle}}</strong></template></nav></template>
    <template v-else-if="spatialView"><button class="crumb-home" :disabled="navigationBusy" :aria-label="`返回项目 ${currentProject?.name}`" @click="breadcrumb('project')">空间总览</button><template v-if="breadcrumbRoom&&view!=='overview'"><ChevronRight :size="13"/><button :disabled="navigationBusy" @click="breadcrumb('room')" :aria-label="`返回机房 ${breadcrumbRoom.name}`">{{breadcrumbRoom.name}}</button></template><template v-if="breadcrumbModule&&['module','elevation'].includes(view)"><ChevronRight :size="13"/><button :disabled="navigationBusy" @click="breadcrumb('module')" :aria-label="`返回微模块 ${breadcrumbModule.name}`">{{breadcrumbModule.name}}</button></template><template v-if="breadcrumbRack&&(view==='elevation'||modal==='device'||modal==='rack')"><ChevronRight :size="13"/><button :disabled="navigationBusy" @click="breadcrumb('rack')">{{breadcrumbRack.name}}</button></template></template>
    <template v-else><ChevronRight :size="13"/><button :disabled="navigationBusy" :aria-label="'返回'+title" @click="navigateWorkspace(view)">{{title}}</button></template>
    <template v-if="editingPage"><ChevronRight :size="13"/><strong aria-current="page">{{modal==='device'?'编辑设备':modal==='rack'?'编辑机柜':modal==='model'?'编辑型号':modal==='renameProject'?'编辑项目':modal==='renameRoom'?'编辑机房':modal==='wizard'?'创建空间':modal==='import'?'导入设备':modal==='template'?'编辑模板':modal==='initialize'?'初始化机房':'编辑微模块'}}</strong></template></nav><div class="topbar-right"><ViewControls/><span class="local-pill"><span class="status-dot"></span>本地部署</span><span class="divider"></span><button class="icon-button" aria-label="刷新数据" :disabled="loading" @click="load"><RefreshCw :size="17" :class="{spin:loading}"/></button><slot name="account"></slot></div></header>
   <main v-show="!editingPage">
    <div v-if="topologyReturn&&view!=='topology'" class="return-context"><button class="secondary" @click="returnToTopology">← 返回原网络拓扑</button><span>当前正在查看设备的机房位置</span></div><section class="page-heading"><div><div class="eyebrow">DATACENTER / {{view==='overview'?'SPATIAL OVERVIEW':view==='topology'?'NETWORK TOPOLOGY':view==='elevation'?'RACK ELEVATION':view==='assets'?'ASSET REGISTER':view==='templates'?'LAYOUT TEMPLATES':view==='models'?'MODEL LIBRARY':view==='room'?'ROOM OVERVIEW':view==='module'?'MODULE LAYOUT':'CHANGE AUDIT'}}</div><h1 :aria-label="title">{{title}}<span class="heading-badge" aria-hidden="true">{{view==='models'?'标准化':view==='audit'?'可追溯':'WORKSPACE'}}</span></h1></div><div class="heading-actions"><template v-if="view==='templates'"></template><template v-else-if="view==='models'"><button class="primary" @click="editModel()"><Plus :size="16"/>新增型号</button></template>
    <template v-if="view==='assets'"><a class="button secondary" href="/api/export/devices.csv" download><Download :size="16"/>导出台账</a><button class="primary" @click="editDevice()"><Plus :size="16"/>新增设备</button></template><template v-else-if="view==='overview'"><button class="primary" @click="openInitialize"><Upload :size="16"/>初始化机房</button><ActionMenu><button @click="newPlan">手动创建机房</button></ActionMenu></template><template v-else-if="view==='room'"><button class="primary" @click="openInitialize"><Upload :size="16"/>导入初始化</button><ActionMenu><button @click="newPlan();wizard.site_id=siteID">新增微模块</button><button @click="rename('room')">编辑机房详情</button><a :href="`/api/export/plan.json?siteId=${siteID}`" download>导出规划</a></ActionMenu></template><template v-else-if="['module','elevation'].includes(view)"><button class="primary" @click="openImport"><Upload :size="16"/>导入设备</button><button class="secondary" aria-label="编辑微模块详细信息" @click="openLayout()"><Settings2 :size="15"/>编辑微模块</button><ActionMenu label="模块更多操作"><button class="danger-text" :disabled="busy" @click="openSpaceDelete('module',moduleID)">删除微模块</button><button aria-label="保存当前布局为模板" @click="saveModuleTemplate">存为布局模板</button></ActionMenu></template><template v-else-if="view==='audit'"><button class="secondary" :disabled="busy" title="移除纯图形操作和未变化记录，保留业务变更并精简正文" @click="compactAudits">精简历史记录</button><button class="secondary" :disabled="busy" @click="loadAudits"><RefreshCw :size="16"/>刷新记录</button></template></div></section>
    <div v-if="loadError" class="error-banner" role="alert">连接失败：{{loadError}}。当前显示上次读取的数据，请刷新后再操作。</div>
    <ProjectOverview v-if="view==='overview'" :state="state" :project-id="projectID" @room="enterRoom" @assets="view='assets'"/>
    <template v-else-if="['room','module','elevation'].includes(view)">
     <section v-if="view==='room'" class="stats-grid room-stats-strip"><article class="stat-card"><div class="stat-top"><span>规划机柜</span><Server :size="18"/></div><div class="stat-value">{{siteRacks.length.toString().padStart(2,'0')}}<small>台</small></div><div class="stat-foot"><span class="small-tag">42U</span>{{modules.length}} 个微模块 · {{currentSite?.name.split('·')[0]}}</div></article><article class="stat-card"><div class="stat-top"><span>设备资产</span><HardDrive :size="18"/></div><div class="stat-value">{{siteDevices.length.toString().padStart(2,'0')}}<small>台</small></div><div class="stat-foot"><span class="status-dot"></span>{{siteDevices.filter(d=>!!d.rackId).length}} 台已上架<span class="muted">/ 手动维护台账</span></div></article><article class="stat-card"><div class="stat-top"><span>U 位使用率</span><Layers3 :size="18"/></div><div class="stat-value">{{usage}}<small>%</small><div class="mini-bars"><i v-for="i in 12" :key="i" :class="{filled:i<=Math.ceil(usage/100*12)}" :style="{height:`${12+i*1.8}px`}"></i></div></div><div class="stat-foot">台账占用 {{totalUsed}} U<span class="muted">/ 规划 {{siteRacks.length*42}} U</span></div></article><article class="stat-card"><div class="stat-top"><span>待上架设备</span><Box :size="18"/></div><div class="stat-value">{{siteDevices.filter(d=>!d.rackId).length.toString().padStart(2,'0')}}<small>台</small></div><div class="stat-foot"><span :class="['status-dot',{'amber':siteDevices.some(d=>!d.rackId)}]"></span>{{siteDevices.some(d=>!d.rackId)?'请检查空间或待确认型号':'机位分配无待处理项'}}</div></article></section>
     <RoomOverview @delete-module="id=>openSpaceDelete('module',id)" @entrance="saveEntrance" @position="positionModule" @move="moveModule" :busy="busy" v-if="view==='room'" :state="state" :project-id="projectID" :site-id="siteID" :selected-module="moduleID" @open="openModule" @room="enterRoom"/>
     <section v-if="view!=='room'" id="module-detail" class="context-bar module-context"><label class="module-switcher">当前微模块<select v-model="moduleID" aria-label="切换微模块"><option v-for="m in modules" :key="m.id" :value="m.id">{{m.name}}</option></select></label><div class="view-switch" role="group" aria-label="微模块展示方式"><button :class="{active:view==='module'}" :aria-pressed="view==='module'" aria-label="俯视图" @click="view='module'"><LayoutGrid :size="16"/>布局排列</button><button :class="{active:view==='elevation'}" :aria-pressed="view==='elevation'" aria-label="立面图" @click="view='elevation'"><Server :size="16"/>柜内设备</button></div></section>
     <div v-if="view==='module'&&currentModule" class="spatial-layout">
      <section class="panel floor-panel"><div class="panel-heading"><div><span class="panel-dot"></span><h2>{{currentModule.name}}</h2><span class="text-badge">{{currentModule.type==='double'?'双排 · 冷通道':'单排 · 微模块'}}</span></div><div class="zoom-controls"><DiagramExport :title="(currentModule?.name||'微模块')+'布局图'" :scope="[currentProject?.name,currentSite?.name,currentModule?.name].filter(Boolean).join(' / ')" selector=".floor-panel .floor-svg" :disabled="busy"/><button class="text-button" :aria-expanded="display.details" @click="display.details=!display.details">{{display.details?'收起详情':'显示详情'}}</button><button aria-label="缩小俯视图" :disabled="zoom<=75" @click="zoom-=25"><Minus :size="14"/></button><span>{{zoom}}%</span><button aria-label="放大俯视图" :disabled="zoom>=400" @click="zoom+=25"><Plus :size="14"/></button><button aria-label="适应预览宽度" title="适应宽度" @click="zoom=100;floorPlan?.fit()"><Maximize2 :size="14"/>适应画布</button></div></div>
       <FloorPlan ref="floorPlan" @clear="clearSelection" :selected-infrastructure="selectedInfraID" @move-infrastructure="moveInfrastructure" :busy="busy" @insert-rack="insertCabinet" :module="currentModule" :racks="racks" :devices="moduleDevices" :models="state.models" :infra="state.infra.filter(i=>i.moduleId===moduleID)" :selected="rackID" :zoom="zoom" @select="selectRack" @infrastructure="selectInfra"/>
       <div class="canvas-footer"><span>拖动排列 · 松手保存 · Esc取消</span><span class="selection-caption"><button v-if="selectedInfra||currentRack" class="text-button" aria-label="取消布局选择" @click="clearSelection">取消选择</button>{{selectedInfra?'已选设施：'+selectedInfra.name:currentRack?'已选机柜：'+currentRack.name:'未选择对象'}}</span></div>
      </section>
      <aside v-if="selectedInfra" class="panel detail-panel"><div class="panel-heading selection-heading"><h2>设施详情</h2><button class="icon-button" aria-label="收起设施详情" title="收起详情" @click="display.details=false"><X :size="16"/></button></div><div class="selected-device"><span class="selection-type">已选中 · 基础设施</span><h3>{{selectedInfra.name}}</h3><dl><dt>所在列</dt><dd>{{selectedInfra.side}}列</dd><dt>安装位置</dt><dd>{{selectedInfra.placement==='integrated'?'柜内集成':'列内独立'}} · {{selectedInfra.afterRack===0?'列首':'第'+selectedInfra.afterRack+'柜'+(selectedInfra.placement==='integrated'?'内':'后')}}</dd></dl><button class="primary full" @click="openLayout(selectedInfra)">编辑详细信息</button></div></aside><aside class="panel detail-panel" v-else-if="currentRack"><div class="panel-heading selection-heading"><h2>机柜详情</h2><button class="icon-button" aria-label="收起机柜详情" title="收起详情" @click="display.details=false"><X :size="16"/></button></div><div class="rack-summary"><div class="rack-avatar"><Server :size="30"/></div><div><span class="selection-type">已选中 · 机柜</span><h3>{{currentRack.name}} <span>42U</span></h3><p>{{currentRack.side}}列 · 第{{currentRack.index}}位</p></div></div><div class="capacity-line"><span>U 位占用</span><strong>{{usedU(rackID)}} <small>/ 42 U</small></strong></div><div class="progress-track"><i :style="{width:`${usedU(rackID)/42*100}%`}"></i></div><div class="capacity-details"><span>剩余 <b>{{42-usedU(rackID)}} U</b></span><span>设备 <b>{{rackDevices.length}} 台</b></span></div><div class="detail-divider"></div><div class="section-label">在架设备 <span>{{rackDevices.length}}</span></div><div v-if="!rackDevices.length" class="small-empty"><Box :size="30"/><strong>等待第一台设备</strong><p>导入清单后，将自动分配连续 U 位。</p><button class="text-button" @click="openImport">导入设备清单 <ArrowRight :size="14"/></button></div><div v-else class="rack-device-list"><button v-for="d in rackDevices.slice(0,5)" :key="d.id" @click="deviceID=d.id;view='elevation'"><i :style="{background:roleColors[modelOf(d.modelId)!.role]}"></i><div><strong>{{d.name}}</strong><small>{{d.assetTag}}</small></div><span>U{{d.startU}}</span></button><small v-if="rackDevices.length>5" class="muted">另有 {{rackDevices.length-5}} 台，请查看立面</small></div><button class="primary full" @click="view='elevation'">查看 42U 立面 <ArrowRight :size="15"/></button><button class="secondary full" aria-label="编辑机柜详细信息" @click="editRack"><Settings2 :size="15"/>编辑机柜详情</button></aside><aside v-else class="panel detail-panel selection-empty"><Server :size="32"/><h2>选择机柜或设施</h2><p>点击图中对象查看详情，拖动调整排列。</p></aside>
     </div>
     <div v-else-if="view==='elevation'" class="elevation-layout"><section class="panel elevation-panel"><div class="panel-heading"><div><h2>42U 机柜立面</h2><span class="text-badge">{{currentModule?.name}}</span></div><div><DiagramExport :title="(currentModule?.name||'微模块')+'机柜立面图'" :scope="[currentProject?.name,currentSite?.name,currentModule?.name].filter(Boolean).join(' / ')+' · 当前显示 '+shownRacks.length+' 个机柜'" selector=".elevation-panel .rack-elevation" :disabled="busy||!!dragDevices.active.value||!shownRacks.length"/><button class="text-button" :aria-expanded="display.tools" @click="display.tools=!display.tools">{{display.tools?'收起工具':'显示工具'}}</button><button class="text-button" :aria-expanded="display.details" @click="display.details=!display.details">{{display.details?'收起详情':'显示详情'}}</button></div></div><div class="role-legend"><span v-for="(name,role) in roleNames" :key="role"><i :style="{background:roleColors[role]}"></i>{{name}}</span></div><div class="rack-workbench-toolbar"><div class="rack-row-filter"><button :class="{active:rackRow==='all'}" @click="rackRow='all';compareMode=false">全部列</button><button v-for="side in currentModule?.type==='double'?['L','R']:['L']" :key="side" :class="{active:rackRow===side}" @click="rackRow=side;compareMode=false">{{side}}列</button></div><button class="secondary" :aria-pressed="compareMode" @click="toggleCompare">{{compareMode?'查看全部':'两柜并排'}}</button><label v-if="compareMode" class="compare-target">目标柜<select v-model="compareRackID" aria-label="并排目标机柜"><option v-for="r in racks.filter(r=>r.id!==rackID)" :key="r.id" :value="r.id">{{r.name}}（{{r.side}}列）</option></select></label><label class="rack-zoom">柜体大小<input v-model.number="elevationScale" type="range" min="55" max="120" step="5" aria-label="立面柜体大小"/></label><button class="text-button" @click="elevationScale=70;compareMode=false;rackRow='all'">紧凑总览</button></div><div class="rack-navigator" aria-label="快速定位机柜"><button v-for="r in racks" :key="r.id" :class="{active:rackID===r.id}" :aria-label="`定位机柜 ${r.name}`" @click="rackRow='all';focusRack(r.id)"><span>{{r.name}}</span><i><b :style="{width:usedU(r.id)/42*100+'%'}"></b></i><small>{{usedU(r.id)}}U · {{r.side}}列</small></button></div><p v-if="dragDevices.active.value?.moved" class="drag-status" role="status">{{dragDevices.target.value?`${rackName(dragDevices.target.value.rackId)} · U${dragDevices.target.value.startU} · ${dragDevices.target.value.valid?'释放完成移动':dragDevices.target.value.reason}`:'将设备拖到目标机柜的U位区域'}} · Esc取消</p><div :class="['elevation-scroll',{'compare-mode':compareMode}]" :style="{'--rack-card-width':237*elevationScale/100+'px'}" @pointermove="dragDevices.move" @pointerup="dragDevices.end" @pointercancel="dragDevices.cancel" @keydown="dragDevices.key"><RackElevation v-for="rack in shownRacks" :key="rack.id" :rack="rack" :devices="moduleDevices" :models="state.models" :selected="deviceID" :focused="rackID===rack.id" :drop="dragDevices.target.value" :drag-height="dragDevices.height.value" :dragging-id="dragDevices.active.value?.id" @drag-start="dragDevices.start" @select="deviceID=$event;rackID=rack.id" @move="moveDevice"/></div></section><aside class="panel placement-panel"><div class="panel-heading"><h2>{{selectedDevice?'设备详情':'待上架区'}}</h2><span class="text-badge">{{pending.length}} 台待分配</span></div><template v-if="selectedDevice"><div class="selected-device"><span class="selection-type">已选中 · 设备</span><div class="device-icon" :style="{color:roleColors[modelOf(selectedDevice.modelId)!.role]}"><HardDrive :size="32"/></div><h3>{{selectedDevice.name}}</h3><p>{{selectedDevice.assetTag}}</p><dl><dt>型号</dt><dd>{{modelOf(selectedDevice.modelId)?.name}}</dd><dt>机位</dt><dd>{{selectedDevice.rackId?rackName(selectedDevice.rackId)+' · U'+selectedDevice.startU:'待上架'}}</dd><dt>IP 地址</dt><dd>{{selectedDevice.ip||'未录入'}}</dd><dt>SN</dt><dd>{{selectedDevice.sn||'未录入'}}</dd></dl><button class="primary full" @click="editDevice(selectedDevice)"><Settings2 :size="15"/>编辑详细信息</button><ActionMenu v-if="selectedDevice.rackId" label="设备更多操作"><button :disabled="busy" @click="moveDevice(selectedDevice.id,'',0);deviceID=''">移至待上架区</button></ActionMenu><button class="text-button" @click="deviceID=''">返回待上架列表</button></div></template><template v-else><details class="compact-help"><summary>操作帮助</summary><p>将设备拖入机柜，或通过编辑表单指定机柜和起始 U 位。</p></details><div v-if="!pending.length" class="small-empty"><Check :size="30"/><strong>暂无待上架设备</strong><p>新设备可从 CSV 批量导入。</p></div><div class="pending-list"><button v-for="d in pending" :key="d.id" draggable="true" @dragstart="drag($event,d.id)" @click="deviceID=d.id"><HardDrive :size="18"/><div><strong>{{d.name}}</strong><small>{{modelOf(d.modelId)?.uHeight||'待确认'}} U · {{d.assetTag}}</small></div></button></div><button class="secondary full" @click="openImport"><Upload :size="15"/>导入设备</button></template></aside></div>
     
    </template>
    <template v-if="view==='assets'"><section class="panel"><div class="table-toolbar"><div class="search-box"><Search :size="17"/><input v-model="query" placeholder="搜索设备、型号、IP 或 SN" aria-label="搜索设备"/></div><select v-model="siteID" aria-label="台账机房"><option v-for="s in sites" :key="s.id" :value="s.id">{{s.name}}</option></select><select v-model="statusFilter" aria-label="筛选设备状态"><option value="">全部状态</option><option v-for="(name,key) in statuses" :key="key" :value="key">{{name}}</option></select><button class="secondary" @click="openImport"><Upload :size="15"/>CSV 导入</button></div><div class="table-scroll"><table><thead><tr><th>设备 / 资产编号</th><th>型号 / 角色</th><th>模块 / 机位</th><th>IP / SN</th><th>资产状态</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="d in pageDevices" :key="d.id"><td><div class="table-device"><div class="asset-icon" :style="{color:roleColors[modelOf(d.modelId)!.role]}"><HardDrive :size="19"/></div><div><strong>{{d.name}}</strong><small>{{d.assetTag}}</small></div></div></td><td><strong>{{modelOf(d.modelId)?.name}}</strong><small>{{roleNames[modelOf(d.modelId)!.role]}} · {{modelOf(d.modelId)?.uHeight||'待确认'}} U</small></td><td><strong>{{moduleName(d.moduleId)}}</strong><small>{{rackName(d.rackId)}}<template v-if="d.rackId"> · U{{d.startU}}–{{d.startU+modelOf(d.modelId)!.uHeight-1}}</template></small></td><td><strong class="mono">{{d.ip||'—'}}</strong><small>{{d.sn||'SN 未录入'}}</small></td><td><span :class="['status-badge',d.status]">{{statuses[d.status]}}</span></td><td><div class="table-actions"><button @click="editDevice(d)">编辑</button><button class="danger-text" @click="remove('devices',d.id,d.name)">删除</button></div></td></tr></tbody></table><div v-if="!filteredDevices.length" class="empty-state"><div class="empty-icon"><ClipboardList :size="36"/></div><h3>{{query||statusFilter?'没有匹配的设备':'把设备清单，变成清晰的机房资产'}}</h3><p>{{query||statusFilter?'调整搜索关键词或筛选条件。':'上传 CSV 清单，系统将展开逐台设备并自动分配连续 U 位。'}}</p><button v-if="!query&&!statusFilter" class="primary" @click="openImport"><Upload :size="16"/>导入第一份清单</button><button v-if="!query&&!statusFilter" class="text-button" @click="download('示例设备清单.csv','\ufeff'+sampleCSV,'text/csv')">下载示例 CSV</button></div></div><div class="table-footer"><span>共 {{filteredDevices.length}} 台设备 · 每页 20 条</span><div><button class="secondary small-button" :disabled="assetPage<=1" @click="assetPage--">上一页</button><span>{{assetPage}} / {{Math.max(1,Math.ceil(filteredDevices.length/20))}}</span><button class="secondary small-button" :disabled="assetPage*20>=filteredDevices.length" @click="assetPage++">下一页</button></div></div></section></template>
    <TemplateLibrary v-else-if="view==='templates'" :state="state" @edit="editTemplate" @use="useTemplate" @saved="state=$event"/><template v-else-if="view==='models'"><details class="compact-help"><summary>型号填写帮助</summary><p>0U表示高度待确认，暂不上架。端口文字仅作台账说明。</p></details><section class="panel"><div class="table-toolbar"><div class="search-box"><Search :size="17"/><input v-model="query" placeholder="搜索型号、厂商或设备角色" aria-label="搜索型号"/></div><span class="muted">{{filteredModels.length}} 个标准型号</span></div><div class="table-scroll"><table><thead><tr><th>设备型号</th><th>角色</th><th>高度</th><th>端口说明</th><th>引用设备</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="m in filteredModels" :key="m.id"><td><strong>{{m.name}}</strong><small>{{m.vendor||'厂商待确认'}}</small></td><td><span class="role-tag" :style="{color:roleColors[m.role]}"><i :style="{background:roleColors[m.role]}"></i>{{roleNames[m.role]}}</span></td><td><span :class="['status-badge',m.uHeight?'installed':'pending']">{{m.uHeight?m.uHeight+' U':'待确认'}}</span></td><td class="port-description">{{m.ports||'—'}}</td><td>{{state.devices.filter(d=>d.modelId===m.id).length}} 台</td><td><div class="table-actions"><button @click="editModel(m)">编辑</button><button class="danger-text" @click="remove('models',m.id,m.name)">删除</button></div></td></tr></tbody></table><div v-if="!filteredModels.length" class="empty-state"><Search :size="32"/><h3>没有匹配的型号</h3></div></div></section></template>
    <template v-else-if="view==='audit'"><div class="audit-summary"><ShieldCheck :size="22"/><div><strong>只记录关键业务变更</strong><p>保留资产、机位、网络连接与配置变更；只保存变化对象。图形位置、配色和重复保存不记录。</p></div><span>数据修订 <b>r{{state.revision}}</b></span></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>变更时间</th><th>动作</th><th>变更摘要</th><th>版本</th><th class="align-right">变更明细</th></tr></thead><tbody><tr v-for="a in audits" :key="a.id"><td class="mono">{{formatTime(a.time)}}</td><td><span class="text-badge">{{a.action}}</span></td><td>{{a.summary}}</td><td class="mono">r{{a.revision}}</td><td class="align-right"><a class="text-button" :href="`/api/audits/${a.id}`" download><Download :size="14"/>下载 JSON</a></td></tr></tbody></table><div v-if="!audits.length" class="empty-state"><History :size="32"/><h3>暂无审计记录</h3></div></div></section></template>
    <KeepAlive><TopologyView ref="topology" v-model:network-id="topologyNetworkID" @navigation="topologyNavigation=$event" v-if="view==='topology'" :state="state" :project-id="projectID" @saved="state=$event" @locate="locateTopologyDevice" @edit-device="editDevice" @create-device="editDevice()" @editing="topologyEditTitle=$event" @initialize="openInitialize"/></KeepAlive>
    <footer class="page-footer"><span>AOM · 机房数字孪生与运维系统</span><span>规划与资产台账 <i></i> 非实时采集数据 <i></i> r{{state.revision}}</span></footer>
   </main>
