 </div>
 <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Activity :size="17"/>{{toast}}<button class="icon-button" aria-label="关闭提示" @click="toast=''"><X :size="15"/></button></div></Transition>
 <component :is="editingPage?EditorPage:Modal" v-if="modal" :title="modal==='wizard'?'标准机房创建向导':modal==='import'?'批量导入设备':modal==='device'?(deviceForm.id?'编辑设备 / 调整机位':'新增设备'):modal==='model'?(modelForm.id?'编辑设备型号':'新增设备型号'):modal==='delete'?'删除记录':modal==='layout'?'微模块布局配置':modal==='renameProject'?'编辑项目':modal==='renameRoom'?'编辑机房':modal==='rack'?'编辑机柜':modal==='template'?'编辑布局模板':modal==='initialize'?'初始化机房':'使用与部署说明'" :wide="['wizard','import','device','layout'].includes(modal)" :busy="busy" @close="modal=''">
  <div v-if="formError" class="error-banner" role="alert">{{formError}}</div>
  <InitializationWizard v-if="modal==='initialize'" :state="state!" :project-id="projectID" :site-id="['room','module','elevation'].includes(view)?siteID:undefined" @saved="state=$event" @refresh="state=$event" @finish="initialized" @busy="busy=$event"/><TemplateEditor v-else-if="modal==='template'&&templateForm" :state="state!" :initial="templateForm" @saved="templateSaved" @busy="busy=$event"/><form v-else-if="modal==='wizard'" @submit.prevent="submitPlan"><div class="wizard-template-picker"><h3>从布局模板开始</h3><select v-model="templateSelection" aria-label="选择布局模板" @change="applyTemplate(templateSelection)"><option value="">自定义布局</option><option v-for="t in state!.templates" :key="t.id" :value="t.id">{{t.name}}</option></select><span class="muted small">选模板 → 确认机房 → 创建</span></div><div class="form-grid"><label>所属项目<select v-model="wizard.project_id" aria-label="规划所属项目" @change="wizard.site_id='' "><option v-for="project in projects" :key="project.id" :value="project.id">{{project.name}}</option><option value="">＋ 创建新项目</option></select></label><label v-if="!wizard.project_id">新项目名称<input v-model="wizard.project_name" required maxlength="80" placeholder="例如：算力中心一期"/></label></div><div class="form-grid wizard-room-fields"><label>创建方式<select aria-label="创建方式" v-model="wizard.site_id"><option value="">创建新机房</option><option v-for="s in state!.sites.filter(s=>s.projectId===wizard.project_id)" :key="s.id" :value="s.id">向 {{s.name}} 添加模块</option></select></label><label v-if="!wizard.site_id">机房名称<input v-model="wizard.site_name" required maxlength="80" placeholder="例如：点位 3 · 边缘机房"/></label><label v-else>目标机房<input :value="state!.sites.find(s=>s.id===wizard.site_id)?.name" disabled/></label></div><datalist id="wizard-products"><option v-for="product in moduleProducts" :key="product" :value="product"/></datalist><div class="form-section-heading"><h3>微模块规划</h3><button type="button" class="text-button" :disabled="wizard.modules.length>=8" @click="wizard.modules.push({name:`微模块 ${wizard.modules.length+1}`,type:'single',rack_count:4,rack_left:4,rack_right:4,u_height:42})"><Plus :size="14"/>增加模块</button></div><div v-for="(m,index) in wizard.modules" :key="index" class="module-form"><div class="module-form-title"><span>MODULE {{String(index+1).padStart(2,'0')}}</span><button v-if="wizard.modules.length>1" type="button" class="icon-button" :aria-label="`删除模块 ${index+1}`" @click="wizard.modules.splice(index,1)"><X :size="15"/></button></div><div class="form-grid"><label>点位标识<input v-model="m.point" maxlength="80" placeholder="例如：点位1"/></label><label>微模块型号<input v-model="m.product_model" list="wizard-products" maxlength="120" placeholder="选择或输入型号"/></label><label>模块名称<input v-model="m.name" required maxlength="80"/></label><label>排列方式<select aria-label="排列方式" v-model="m.type"><option value="single">单排微模块</option><option value="double">双排冷通道</option></select></label><label v-if="m.type==='single'">机柜数量<input v-model.number="m.rack_count" @change="delete m.rack_names" required type="number" min="1" max="24"/></label><template v-else><label>左列机柜数<input v-model.number="m.rack_left" @change="delete m.rack_names" required type="number" min="1" max="12"/></label><label>右列机柜数<input v-model.number="m.rack_right" @change="delete m.rack_names" required type="number" min="1" max="12"/></label></template><label>机柜标准<input value="42U · 标准机柜" disabled/></label></div><div v-if="m.layout" class="module-infra-override"><p class="field-note">已载入 {{m.layout.length}} 项精确设施位置，将使用此布局；下方公共数量不覆盖已载入的位置。</p><button type="button" class="text-button" @click="delete m.layout">清除位置，按设施数量重新生成</button></div><div v-if="m.infra&&!m.layout" class="module-infra-override"><p class="field-note">此模块使用导入文件中的独立基础设施配置。</p><div class="form-grid three"><label>模块配电槽位<input v-model.number="m.infra.power" type="number" min="0" max="8" required/></label><label>模块空调槽位<input v-model.number="m.infra.ac" type="number" min="0" max="8" required/></label><label>模块环境槽位<input v-model.number="m.infra.env" type="number" min="0" max="8" required/></label></div><button type="button" class="text-button" @click="delete m.infra">改用下方公共配置</button></div></div><div class="form-section-heading"><h3>每模块基础设施预留</h3><span class="muted small">独立槽位，不扣减机柜 U 位</span></div><div class="form-grid three"><label>配电槽位<input v-model.number="wizard.infra.power" required type="number" min="0" max="8"/></label><label>空调槽位<input v-model.number="wizard.infra.ac" required type="number" min="0" max="8"/></label><label>环境监测槽位<input v-model.number="wizard.infra.env" required type="number" min="0" max="8"/></label></div><div class="modal-actions"><label class="button secondary file-button"><FileJson :size="15"/>载入规划 JSON<input type="file" accept=".json" @change="readPlan"/></label><div><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="16"/>生成机房基座 <ArrowRight :size="16"/></button></div></div></form>
  <div v-else-if="modal==='import'"><details class="compact-help"><summary>导入填写帮助</summary><p>型号与数量自动展开，IP/SN可空；批量行不能填写单个IP/SN。先预览再入库，容量不足或U高未知的设备保留待上架。</p></details><label class="full-label">目标模块<select aria-label="目标模块" v-model="importModule"><optgroup v-for="s in sites" :key="s.id" :label="s.name"><option v-for="m in state!.modules.filter(m=>m.siteId===s.id)" :key="m.id" :value="m.id">{{m.name}}</option></optgroup></select></label><label class="upload-zone"><Upload :size="27"/><strong>{{csvName||'选择 UTF-8 编码的 CSV 清单'}}</strong><span>支持中文列头 · 最大 2MiB · 每次最多展开 2,000 台</span><input type="file" accept=".csv,text/csv" @change="readCSV"/></label><div class="import-tools"><button class="text-button" @click="download('设备导入模板.csv','\ufeffmodel,quantity,name,asset_prefix,ip,sn,note\n','text/csv')"><Download :size="14"/>下载空白模板</button><button class="text-button" @click="csvContent=sampleCSV;csvName='示例设备清单.csv（19台，非真实资产）';preview=null">使用示例清单</button></div><details v-if="csvContent" class="csv-source"><summary>查看 / 编辑 CSV 内容</summary><textarea v-model="csvContent" rows="6" spellcheck="false" aria-label="CSV内容"></textarea></details><template v-if="preview"><div class="import-stats"><div><strong>{{preview.total}}</strong><span>展开设备</span></div><div><strong>{{preview.placed}}</strong><span>可上架</span></div><div><strong class="amber-text">{{preview.pending}}</strong><span>待上架</span></div></div><div class="preview-table"><table><thead><tr><th>设备</th><th>资产编号</th><th>分配结果</th></tr></thead><tbody><tr v-for="row in preview.rows.slice(0,100)" :key="row.device.id"><td>{{row.device.name}}</td><td class="mono">{{row.device.assetTag}}</td><td><span v-if="row.device.rackId" class="green-text">{{rackName(row.device.rackId)}} · U{{row.device.startU}}–{{row.device.startU+modelOf(row.device.modelId)!.uHeight-1}}</span><span v-else class="amber-text">{{row.reason}}</span></td></tr></tbody></table></div><p v-if="preview.total>100" class="muted small">仅预览前100台，确认时将导入全部{{preview.total}}台。</p></template><div class="modal-actions"><span class="muted small">{{preview?'预览未写入数据库':'必填列：model / quantity（型号 / 数量）'}}</span><div><button class="secondary" @click="modal=''">取消</button><button v-if="!preview" class="primary" :disabled="busy||!csvContent" @click="previewCSV"><LoaderCircle v-if="busy" class="spin" :size="16"/>预览自动排位</button><button v-else class="primary" :disabled="busy" @click="commitCSV"><Check :size="16"/>确认导入 {{preview.total}} 台</button></div></div></div>
  <form v-else-if="modal==='device'" @submit.prevent="saveDevice"><div class="form-grid"><label>资产编号<input v-model="deviceForm.assetTag" required maxlength="80"/></label><label>设备名称<input v-model="deviceForm.name" maxlength="120" placeholder="留空使用型号名称"/></label><label>设备型号<select aria-label="设备型号" v-model="deviceForm.modelId" required><option v-for="m in state!.models" :key="m.id" :value="m.id">{{m.name}} · {{m.uHeight||'待确认'}}U</option></select></label><label>目标模块<select aria-label="目标模块" v-model="deviceForm.moduleId" required @change="deviceForm.rackId='';setDeviceRack()"><optgroup v-for="s in sites" :key="s.id" :label="s.name"><option v-for="m in state!.modules.filter(m=>m.siteId===s.id)" :key="m.id" :value="m.id">{{m.name}}</option></optgroup></select></label><label>IP 地址<input v-model="deviceForm.ip" placeholder="选填 · IPv4 / IPv6"/></label><label>设备 SN<input v-model="deviceForm.sn" maxlength="120" placeholder="选填 · 非空时必须唯一"/></label></div><div class="form-section-heading"><h3>机位分配</h3><label v-if="!deviceForm.id" class="checkbox-label"><input v-model="autoPlace" type="checkbox"/>自动寻找连续 U 位</label></div><div v-if="deviceForm.id||!autoPlace" class="form-grid"><label>机柜<select aria-label="机柜" v-model="deviceForm.rackId" @change="setDeviceRack"><option value="">暂不上架</option><option v-for="r in deviceRacks" :key="r.id" :value="r.id">{{r.name}} · 剩余{{42-usedU(r.id)}}U</option></select></label><label>起始 U 位<input v-model.number="deviceForm.startU" type="number" :min="deviceForm.rackId?1:0" :max="42" :disabled="!deviceForm.rackId" required/></label><label>资产状态<select aria-label="资产状态" v-model="deviceForm.status"><option :value="deviceForm.rackId?'installed':'pending'">{{deviceForm.rackId?'已上架':'待上架'}}</option><option value="maintenance">维护中</option></select></label></div><p v-else class="panel-note">从目标模块首柜底部开始排位。高度未知或空间不足时保留为待上架。</p><label class="full-label">备注<textarea v-model="deviceForm.note" maxlength="2000" rows="3" placeholder="用途、业务分组或现场备注"></textarea></label><div class="modal-actions"><button v-if="deviceForm.id" type="button" class="text-button danger-text" @click="remove('devices',deviceForm.id,deviceForm.name)">删除设备台账</button><span v-else class="muted small">保存实际变更的前后明细</span><div><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy">保存设备</button></div></div></form>
  <form v-else-if="modal==='model'" @submit.prevent="saveModel"><div class="form-grid"><label class="span-two">型号名称<input v-model="modelForm.name" required maxlength="100" placeholder="例如：KunTai R722 K2"/></label><label>厂商<input v-model="modelForm.vendor" maxlength="80"/></label><label>设备角色<select aria-label="设备角色" v-model="modelForm.role"><option v-for="(name,role) in roleNames" :key="role" :value="role">{{name}}</option></select></label><label>设备高度（U）<input v-model.number="modelForm.uHeight" required type="number" min="0" max="42"/></label><p class="field-note">0 表示待确认，禁止自动上架。修改已引用型号的高度会重新校验所有在架设备。</p></div><label class="full-label">端口模板说明<textarea v-model="modelForm.ports" rows="3" maxlength="500" placeholder="例如：48 × 25G + 8 × 100G"></textarea></label><div class="modal-actions"><span></span><div><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy">保存型号</button></div></div></form>
  <div v-else-if="modal==='delete'"><p class="delete-message">确定删除「<strong>{{deleteTarget?.name}}</strong>」？{{deleteTarget?.kind==='devices'?'设备占用的机位将释放，历史审计快照仍会保留。':'已被设备引用的型号不能删除。'}}</p><div class="modal-actions"><span></span><div><button class="secondary" @click="modal=''">取消</button><button class="danger" :disabled="busy" @click="confirmDelete">确认删除</button></div></div></div>
  <form v-else-if="modal==='rack'" @submit.prevent="saveRack"><label class="full-label">机柜名称<input v-model="rackEditName" required maxlength="80"/></label><details class="compact-help"><summary>操作帮助</summary><p>位置：{{currentModule?.name}} / {{currentRack?.side}}列第{{currentRack?.index}}位。调整位置请返回预览图拖动机柜。</p></details><div class="modal-actions"><span class="muted small">修改名称保留设备、机位和连接</span><button class="primary" :disabled="busy">保存机柜</button></div></form>
  <LayoutEditor @request-delete="openSpaceDelete" @deleted="modal='';moduleID=modules[0]?.id||'';view='room'" v-else-if="modal==='layout'&&layoutModule" :state="state!" :module="layoutModule" :initial-infra="layoutInitial" @saved="onLayoutSaved" @busy="busy=$event"/>
  <form v-else-if="modal==='renameProject'||modal==='renameRoom'" @submit.prevent="saveName"><label>名称<input v-model="renameName" required maxlength="80"/></label><label v-if="modal==='renameRoom'" class="full-label">所属项目<select v-model="renameProject" aria-label="机房所属项目"><option v-for="project in projects" :key="project.id" :value="project.id">{{project.name}}</option></select></label><div class="modal-actions"><span class="muted small">保留机房内所有微模块和设备</span><button class="primary" :disabled="busy">保存</button></div></form>
  <div v-else class="help-content"><div class="info-banner"><Monitor :size="20"/><span>一个后台程序，直接通过浏览器使用。全部页面资源随程序打包，不依赖外部 CDN。</span></div><h3>建议使用顺序</h3><ol><li>先选择项目和机房，在总览图中查看微模块、柜列与设施；通过创建向导增加项目、机房和单/双排模块。</li><li>在“型号库”确认设备高度，尤其是核心交换机；C500在微模块布局中配置。</li><li>导入 CSV，检查预览中的机位及待上架原因，确认后入库。</li><li>在“机柜立面”拖拽调整 U 位，或编辑设备表单进行跨柜移动。</li><li>在“变更审计”下载变更明细，追溯重要操作。</li></ol><h3>单机 / 局域网与迁移</h3><p>默认本机地址：<code>http://localhost:8080</code>。局域网使用启动脚本启用HTTPS，浏览器访问“https://服务器IP:8080”，先核对并信任证书。</p><p>停止后台后，复制整个运行目录及其 <code>data</code> 子目录到其他电脑，使用对应操作系统的可执行文件启动。Windows 和 Linux 使用对应运行包，登录仍需原账号密码。</p><h3>账号与加密</h3><p>右上角用户菜单可修改密码、退出登录或查看系统信息。数据保存在data/app.vault，忘记密码无法恢复。导入后保留的app.db及旧备份仍可能为明文，请核对后妥善处理。</p><h3>当前边界</h3><p>本期是空间与资产台账，设备状态由人工维护，不代表实际在线状态。基础设施按列内独立或柜内集成展示，位置与占U须现场确认。网络拓扑可维护链路、端口占用和网络分区；配置不会下发设备，实时采集、工单、备件与 ZIP 恢复在后续阶段实施。</p><div class="modal-actions"><span class="muted small">{{systemInfo.name}}</span><button class="primary" @click="modal=''">知道了</button></div></div>
 </component>
 <SpaceDeleteDialog v-if="spaceDelete&&state" :state="state" :kind="spaceDelete.kind" :id="spaceDelete.id" @saved="spaceDeleted" @refresh="state=$event" @busy="busy=$event" @close="spaceDelete=null"/>
</template>
